// Cradler needs lowercase snake_case names, and each column should keep one type.
const settings = $('Settings').first().json;
const toSnake = (s) => String(s).replace(/([a-z0-9])([A-Z])/g, '$1_$2').toLowerCase()
  .replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '').replace(/^([0-9])/, '_$1');
const RESERVED = ['id', 'created_at', 'updated_at'];

let table = toSnake(settings['Table name']) || 'my_data';
if (table === 'data_tables') table = 'my_data_tables';

const raw = $input.all().map((i) => i.json);
if (!raw.length) throw new Error('The file has no rows.');

// Map original headers to unique snake_case column names.
const headers = Object.keys(raw[0]);
const used = new Set();
const colOf = {};
headers.forEach((h, i) => {
  let c = toSnake(h) || `col_${i + 1}`;
  if (RESERVED.includes(c)) c = `src_${c}`;
  while (used.has(c)) c = `${c}_${i + 1}`;
  used.add(c); colOf[h] = c;
});

const isNum = (v) => /^-?\d+(\.\d+)?$/.test(v) && !/^0\d/.test(v);
const isBool = (v) => /^(true|false)$/i.test(v);
const type = {};
for (const h of headers) {
  const vals = raw.map((r) => String(r[h] ?? '').trim()).filter((v) => v !== '');
  type[h] = vals.length && vals.every(isNum) ? 'number' : vals.length && vals.every(isBool) ? 'boolean' : 'text';
}

const rows = raw.map((r) => {
  const out = {};
  for (const h of headers) {
    const v = String(r[h] ?? '').trim();
    if (v === '') continue;
    out[colOf[h]] = type[h] === 'number' ? Number(v) : type[h] === 'boolean' ? /^true$/i.test(v) : v;
  }
  return out;
});

const size = settings.batch_size || 500;
const columns = headers.map((h) => `${colOf[h]}:${type[h]}`).join(', ');
const batches = [];
for (let i = 0; i < rows.length; i += size) {
  batches.push({ json: { table, columns, total_rows: rows.length, file: settings['Data file']?.filename || '', rows: rows.slice(i, i + size) } });
}
return batches;

